function AskAboutKashCal(): ReactNode {
  const encoded = encodeURIComponent(ASK_QUERY);
  return (
    <div className={styles.ask}>
      <span className={styles.askLabel}>Ask about KashCal on</span>
      <ul className={styles.askList}>
        {ASK_LINKS.map((link) => (
          <li key={link.label}>
            <a
              className={styles.askLink}
              href={link.href(encoded)}
              target="_blank"
              rel="noopener noreferrer"
              title={`Ask about KashCal on ${link.label}.`}
              aria-label={`Ask about KashCal on ${link.label}.`}>
              {link.icon}
            </a>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default function FooterLayout({
  style,
  links,
  logo,
  copyright,
}: {
  style: string;
  links: ReactNode;
  logo: ReactNode;
  copyright: ReactNode;
}): ReactNode {
  return (
    <footer
      className={clsx(ThemeClassNames.layout.footer.container, 'footer', {
        'footer--dark': style === 'dark',
      })}>
      <div className="container container-fluid">
        {links}
        <AskAboutKashCal />
        {(logo || copyright) && (
          <div className="footer__bottom text--center">
            {logo && <div className="margin-bottom--sm">{logo}</div>}
            {copyright}
          </div>
        )}
      </div>
    </footer>
  );
}
